"use client";
/* eslint-disable @next/next/no-img-element -- user-selected blob URLs are local previews */
import { Check, ChevronLeft, ChevronRight, Clipboard, ImagePlus, LoaderCircle, Trash2 } from "lucide-react";
import { useId, useState } from "react";

const problems=["Tangled or matted","Dry or frizzy","Lace damage","Shedding","Needs restyling","General maintenance"];
const services:Record<string,string>={"Tangled or matted":"Detangling & deep conditioning","Dry or frizzy":"Moisture and frizz care","Lace damage":"Lace/closure assessment","Shedding":"Construction and shedding assessment","Needs restyling":"Restyling and customization","General maintenance":"Maintenance refresh"};
type Upload={file:File;url:string};
type Data={hair:string;length:string;construction:string;problems:string[];severity:string;notes:string;uploads:Record<string,Upload|undefined>;location:string;date:string;handoff:string;instructions:string;name:string;phone:string;email:string;contact:string};
const initial:Data={hair:"",length:"",construction:"",problems:[],severity:"",notes:"",uploads:{},location:"",date:"",handoff:"",instructions:"",name:"",phone:"",email:"",contact:""};
const labels=["Wig info","Problems","Photos","Assessment","Booking","Contact","Confirmation"];

export function AssessmentWizard(){
 const [step,setStep]=useState(0),[data,setData]=useState<Data>(initial),[errors,setErrors]=useState<string[]>([]),[submitting,setSubmitting]=useState(false),[done,setDone]=useState(false),[copied,setCopied]=useState(false);
 const stableId=useId();
 const ref=`RHS-DEMO-${stableId.replace(/[^a-z0-9]/gi,"").slice(-5).toUpperCase().padEnd(5,"0")}`;
 const suggested=[...new Set(data.problems.map(p=>services[p]))];
 const validate=()=>{const e:string[]=[]; if(step===0){if(!data.hair)e.push("Choose a hair type");if(!data.length)e.push("Choose the wig length");if(!data.construction)e.push("Choose the construction type")} if(step===1){if(!data.problems.length)e.push("Select at least one problem");if(!data.severity)e.push("Choose the condition severity")} if(step===2){["Front photo","Back photo","Close-up of damage"].forEach(k=>{if(!data.uploads[k])e.push(`Add a ${k.toLowerCase()}`)})} if(step===4){if(!data.location)e.push("Choose a location");if(!data.date)e.push("Choose a demo date");if(!data.handoff)e.push("Choose drop-off or collection")} if(step===5){if(data.name.trim().length<2)e.push("Enter your full name");if(data.phone.replace(/\D/g,"").length<8)e.push("Enter a valid phone number");if(!/^\S+@\S+\.\S+$/.test(data.email))e.push("Enter a valid email");if(!data.contact)e.push("Choose a preferred contact method")} setErrors(e);return !e.length};
 const next=()=>{if(!validate())return;if(step===5){setSubmitting(true);setTimeout(()=>{setSubmitting(false);setDone(true);setStep(6)},800)}else setStep(s=>Math.min(6,s+1));setErrors([]);document.getElementById("wizard")?.scrollIntoView({behavior:"smooth",block:"start"})};
 const choose=(key:keyof Data,value:string)=>setData(d=>({...d,[key]:value}));
 const upload=(label:string,file?:File)=>{if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setErrors([`${label}: use JPG, PNG, or WebP`]);return}if(file.size>5*1024*1024){setErrors([`${label}: file must be under 5 MB`]);return}const prior=data.uploads[label];if(prior)URL.revokeObjectURL(prior.url);setData(d=>({...d,uploads:{...d.uploads,[label]:{file,url:URL.createObjectURL(file)}}}));setErrors([])};
 const summary=`${ref}\n${data.hair} ${data.length} ${data.construction} wig\nProblems: ${data.problems.join(", ")} (${data.severity})\nSuggested categories: ${suggested.join(", ")}\nPreference: ${data.location}, ${data.date}, ${data.handoff}\nContact: ${data.name}, ${data.contact}`;
 const copy=async()=>{await navigator.clipboard.writeText(summary);setCopied(true);setTimeout(()=>setCopied(false),1800)};
 return <div id="wizard" className="scroll-mt-24 rounded-[1.75rem] border border-[#e5ddea] bg-white shadow-[0_30px_80px_rgba(54,20,65,.12)]">
  <div className="border-b border-[#eee8f1] p-5 md:p-7"><div className="mb-4 flex items-center justify-between"><div><span className="eyebrow text-[#8c557f]">Demo assessment</span><h2 className="modern mt-1 text-xl font-bold text-[#34123d]">Step {step+1} of 7 · {labels[step]}</h2></div><span className="rounded-full bg-[#f1e9f5] px-3 py-1 text-xs font-bold text-[#6d3275]">{Math.round(((step+1)/7)*100)}%</span></div><div className="flex gap-1.5" aria-label={`Progress: step ${step+1} of 7`}>{labels.map((l,i)=><div key={l} className={`h-1.5 flex-1 rounded-full ${i<=step?"bg-[#a33c76]":"bg-[#e9e2ec]"}`}/>)}</div></div>
  <div className="min-h-[510px] p-5 md:p-8">
   {errors.length>0&&<div role="alert" className="mb-6 rounded-xl border border-[#f2b9c9] bg-[#fff2f5] p-4 text-sm text-[#8f2445]"><strong>Please check:</strong><ul className="mt-1 list-disc pl-5">{errors.map(e=><li key={e}>{e}</li>)}</ul></div>}
   {step===0&&<Step title="Tell us about your wig" copy="This helps us frame an initial assessment. A specialist would still inspect the wig in person."><ChoiceGroup label="Hair type" options={["Human hair","Synthetic","Unsure"]} value={data.hair} set={v=>choose("hair",v)}/><ChoiceGroup label="Wig length" options={["Short","Shoulder length","Long","Extra long"]} value={data.length} set={v=>choose("length",v)}/><ChoiceGroup label="Construction" options={["Lace front","Full lace","Closure","Machine-made","Unsure"]} value={data.construction} set={v=>choose("construction",v)}/></Step>}
   {step===1&&<Step title="What needs attention?" copy="Select every issue that applies."><div className="grid gap-3 sm:grid-cols-2">{problems.map(p=><button key={p} type="button" onClick={()=>setData(d=>({...d,problems:d.problems.includes(p)?d.problems.filter(x=>x!==p):[...d.problems,p]}))} className={`focus-ring flex items-center justify-between rounded-xl border p-4 text-left font-semibold ${data.problems.includes(p)?"border-[#a13e78] bg-[#f8edf4] text-[#6c2053]":"border-[#ded5e2] hover:border-[#b58eaf]"}`}>{p}{data.problems.includes(p)&&<Check size={18}/>}</button>)}</div><ChoiceGroup label="Current condition" options={["Mild","Moderate","Severe"]} value={data.severity} set={v=>choose("severity",v)}/><label className="mt-6 block"><span className="mb-2 block text-sm font-bold">Additional notes <span className="font-normal text-[#766978]">(optional)</span></span><textarea value={data.notes} onChange={e=>choose("notes",e.target.value)} rows={4} className="w-full rounded-xl border border-[#dcd3e0] p-4" placeholder="What changed, and what result are you hoping for?"/></label></Step>}
   {step===2&&<Step title="Show us the wig" copy="Photos stay in this browser and are not uploaded for this demonstration."><div className="grid gap-4 md:grid-cols-3">{["Front photo","Back photo","Close-up of damage"].map(label=>{const u=data.uploads[label];return <div key={label} className="relative overflow-hidden rounded-2xl border border-dashed border-[#cdbed2] bg-[#faf7fb]">{u?<>{/* Blob previews are intentionally browser-local and cannot use the Next image optimizer. */}<img src={u.url} alt={`${label} preview`} className="aspect-square w-full object-cover"/><button onClick={()=>{URL.revokeObjectURL(u.url);setData(d=>({...d,uploads:{...d.uploads,[label]:undefined}}))}} className="focus-ring absolute right-2 top-2 grid h-9 w-9 place-items-center rounded-full bg-white text-[#8b2459] shadow" aria-label={`Remove ${label}`}><Trash2 size={16}/></button><label className="block cursor-pointer p-3 text-center text-sm font-bold text-[#6d3275]">Replace<input hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(label,e.target.files?.[0])}/></label></>:<label className="flex aspect-[4/5] cursor-pointer flex-col items-center justify-center p-5 text-center"><ImagePlus className="mb-3 text-[#a33c76]"/><strong>{label}</strong><span className="mt-2 text-xs text-[#807483]">JPG, PNG or WebP · max 5 MB</span><input hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(label,e.target.files?.[0])}/></label>}</div>})}</div></Step>}
   {step===3&&<Step title="Your initial treatment assessment" copy="Based on what you selected, these are the service categories a specialist may explore."><Summary data={data}/><div className="mt-6 rounded-2xl bg-[#f4edf7] p-5"><h3 className="font-bold text-[#481852]">Potential service categories</h3><ul className="mt-3 grid gap-2 sm:grid-cols-2">{suggested.map(s=><li key={s} className="flex gap-2 text-sm"><Check className="text-[#a33c76]" size={17}/>{s}</li>)}</ul></div><p className="mt-6 rounded-xl border border-[#e2cad7] p-4 text-sm leading-6 text-[#675b69]"><strong>No guarantee or quote yet.</strong> Fibre compatibility, construction, previous treatment, and damage must be inspected by a specialist before confirming whether restoration is possible, how long it may take, or what it may cost.</p></Step>}
   {step===4&&<Step title="Choose demo booking preferences" copy="These scheduling choices are fictional and do not reserve a real appointment."><ChoiceGroup label="Illustrative location" options={["Lagos","Abuja"]} value={data.location} set={v=>choose("location",v)}/><ChoiceGroup label="Demo availability" options={["Tue, 17 Nov","Thu, 19 Nov","Sat, 21 Nov"]} value={data.date} set={v=>choose("date",v)}/><ChoiceGroup label="Handover preference" options={["Studio drop-off","Request collection"]} value={data.handoff} set={v=>choose("handoff",v)}/><label className="mt-6 block"><span className="mb-2 block text-sm font-bold">Additional instructions <span className="font-normal text-[#766978]">(optional)</span></span><textarea value={data.instructions} onChange={e=>choose("instructions",e.target.value)} rows={3} className="w-full rounded-xl border border-[#dcd3e0] p-4" placeholder="Any timing or handling notes?"/></label></Step>}
   {step===5&&<Step title="How should we reach you?" copy="Your contact details remain in this browser for this demonstration."><div className="grid gap-4 md:grid-cols-2"><Input label="Full name" value={data.name} set={v=>choose("name",v)} placeholder="Ada Okafor"/><Input label="Phone number" value={data.phone} set={v=>choose("phone",v)} placeholder="0800 000 0000"/><Input label="Email address" type="email" value={data.email} set={v=>choose("email",v)} placeholder="ada@example.com"/><div><ChoiceGroup label="Preferred contact" options={["WhatsApp","Phone","Email"]} value={data.contact} set={v=>choose("contact",v)} compact/></div></div></Step>}
   {step===6&&done&&<Step title="Your demo request is ready" copy="No real booking has been submitted. Keep this summary as a preview of the completed experience."><div className="rounded-2xl bg-[#32113d] p-6 text-white"><span className="text-xs uppercase tracking-widest text-[#dba8cb]">Demo request reference</span><p className="modern mt-2 text-3xl font-extrabold">{ref}</p></div><div className="mt-5"><Summary data={data}/><div className="mt-5 rounded-xl bg-[#fff3f7] p-4 text-sm text-[#78304e]"><strong>Demonstration only.</strong> No information was transmitted, no payment was taken, and no appointment was reserved.</div><button onClick={copy} className="focus-ring mt-5 inline-flex items-center gap-2 rounded-full border border-[#9d3b76] px-5 py-3 font-bold text-[#76295d]"><Clipboard size={17}/>{copied?"Summary copied":"Copy assessment summary"}</button></div></Step>}
  </div>
  <div className="flex items-center justify-between border-t border-[#eee8f1] p-5 md:p-7">{step>0&&step<6?<button onClick={()=>{setStep(s=>s-1);setErrors([])}} className="focus-ring inline-flex items-center gap-1 rounded-full px-3 py-2 font-bold text-[#6c5d70]"><ChevronLeft/>Back</button>:<span/>}{step<6&&<button onClick={next} disabled={submitting} className="focus-ring inline-flex min-w-36 items-center justify-center gap-2 rounded-full bg-[#a33c76] px-6 py-3 font-bold text-white transition hover:bg-[#81285e] disabled:opacity-60">{submitting?<><LoaderCircle className="animate-spin" size={18}/>Creating…</>:<>{step===5?"Create demo request":"Continue"}<ChevronRight size={18}/></>}</button>}</div>
 </div>
}
function Step({title,copy,children}:{title:string;copy:string;children:React.ReactNode}){return <div><h3 className="modern text-2xl font-extrabold text-[#301139] md:text-3xl">{title}</h3><p className="mt-2 mb-7 max-w-2xl text-sm leading-6 text-[#766a78]">{copy}</p>{children}</div>}
function ChoiceGroup({label,options,value,set,compact=false}:{label:string;options:string[];value:string;set:(v:string)=>void;compact?:boolean}){return <fieldset className="mt-6"><legend className="mb-3 text-sm font-bold">{label}</legend><div className={`flex flex-wrap gap-2 ${compact?"md:mt-0":""}`}>{options.map(o=><button type="button" key={o} onClick={()=>set(o)} className={`focus-ring rounded-full border px-4 py-2.5 text-sm font-semibold ${value===o?"border-[#9e3a74] bg-[#9e3a74] text-white":"border-[#d9cfdd] bg-white hover:border-[#a987a5]"}`}>{o}</button>)}</div></fieldset>}
function Input({label,value,set,placeholder,type="text"}:{label:string;value:string;set:(v:string)=>void;placeholder:string;type?:string}){return <label><span className="mb-2 block text-sm font-bold">{label}</span><input type={type} value={value} onChange={e=>set(e.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-[#dcd3e0] px-4 py-3"/></label>}
function Summary({data}:{data:Data}){return <dl className="grid gap-3 rounded-2xl border border-[#e6dce9] p-5 sm:grid-cols-2"><div><dt className="text-xs uppercase tracking-wider text-[#8a7c8d]">Wig</dt><dd className="mt-1 font-bold">{data.hair} · {data.length} · {data.construction}</dd></div><div><dt className="text-xs uppercase tracking-wider text-[#8a7c8d]">Condition</dt><dd className="mt-1 font-bold">{data.severity||"Not selected"}</dd></div><div className="sm:col-span-2"><dt className="text-xs uppercase tracking-wider text-[#8a7c8d]">Selected problems</dt><dd className="mt-1 font-bold">{data.problems.join(", ")}</dd></div>{data.location&&<div><dt className="text-xs uppercase tracking-wider text-[#8a7c8d]">Preference</dt><dd className="mt-1 font-bold">{data.location} · {data.date} · {data.handoff}</dd></div>}{data.name&&<div><dt className="text-xs uppercase tracking-wider text-[#8a7c8d]">Contact</dt><dd className="mt-1 font-bold">{data.name} · {data.contact}</dd></div>}</dl>}
